<?php
require_once 'bootstrap.php';header('Content-Type: application/json; charset=utf-8');
$q=trim($_GET['q']??'');$level=trim($_GET['level']??'');$country=trim($_GET['country']??'');$status=trim($_GET['status']??'');
$sql="SELECT sic_id,entity_name,original_type,network_level,network_rank,rank_color,continent,country,region,province,city,address,latitude,longitude,geo_accuracy,geo_confidence,geocoded_from,geocoded_at,status,parent_sic_id,source_url,source_type,language,meeting,public_contact,website,phone,email,direct_children,network_descendants,public_data_score,is_synthetic FROM dependex_world_registry WHERE 1=1";$p=[];
if($level!==''){$sql.=' AND network_level=?';$p[]=$level;}if($country!==''){$sql.=' AND country=?';$p[]=$country;}if($status!==''){$sql.=' AND status LIKE ?';$p[]='%'.$status.'%';}if($q!==''){$sql.=' AND (entity_name LIKE ? OR city LIKE ? OR region LIKE ? OR country LIKE ? OR address LIKE ? OR sic_id LIKE ?)';for($i=0;$i<6;$i++)$p[]='%'.$q.'%';}$sql.=' ORDER BY network_rank DESC,country,region,city,entity_name LIMIT 5000';$st=db()->prepare($sql);$st->execute($p);echo json_encode($st->fetchAll(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);